UPDATE lessons SET title='Year 3, Week 30, Lesson 1: Staying safe online', data=json_patch(data,'{"child_mission":"Staying safe online means protecting personal information, asking trusted adults before sharing and being kind in digital spaces.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nSort safe/unsafe: using a class code; telling a stranger your address in chat; asking a parent before a new app.\n\nFEEDBACK\nSafe; unsafe; safe.\n\nWATCH FOR\nThinking “everyone online is a friend” is unsafe.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nMake an online-safety charter with eight rules. Role-play two scenarios (what to do). Sign with a parent/teacher that you discussed them.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science and Technology","learning_intention":"Staying safe online means protecting personal information, asking trusted adults before sharing and being kind in digital spaces.","lesson_number":1,"lesson_role":"Investigate","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["ST2-DDT-02"],"parent_notes":"Parent: Marking guidance for the independent task: Make an online-safety charter with eight rules. Role-play two scenarios (what to do). Sign with a parent/teacher that you discussed them. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new object/context, two named observations, claim about online safety linked to that evidence.\n\nParent: Written model 2: Sample misconception: Thinking “everyone online is a friend” is unsafe.. Correction: Safe; unsafe; safe. with evidence.\n\nParent: Likely misconception: Thinking “everyone online is a friend” is unsafe. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses online safety. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about online safety, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Accept a new example with named observations and a claim–evidence link about online safety. Reject title-only labels with no observation. / Accept a misconception plus corrected claim and evidence reason for online safety. Reject wording changes that leave the same error..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for online safety. The other choices miss a key step or use a common mistake.","options":["Safe; unsafe; safe","Thinking “everyone online is a friend” is unsafe","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Sort safe/unsafe: using a class code; telling a stranger your address in chat; asking a parent before a new app. Which response is most accurate?","type":"multiple_choice"},{"correct_index":0,"explanation":"This is the misconception to avoid for online safety; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Thinking “everyone online is a friend” is unsafe","Staying safe online means protecting personal information, asking trusted adults before sharing and being kind in","Safe; unsafe; safe","Careful use of personal and explain why it matters with clear evidence"],"question":"Which statement is a common mistake when working with online safety?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named personal and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence","Thinking “everyone online is a friend” is unsafe","Name personal and explain why it matters only, without linking it to online safety","Apply online safety to new material and name the personal and explain why it matters used"],"question":"Which response best applies online safety with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"Trustworthy science claims rest on observable evidence linked to the claim. The other choices miss a key step or use a common mistake.","options":["Copy a label from the lesson title with no observation","Thinking “everyone online is a friend” is unsafe","Use observable features or measurements as evidence, not appearance alone","Decide from which object looks most exciting"],"question":"New examples: yeast making bread rise, a spinning fan, copper wire, a tadpole. Which claim about online safety is most trustworthy?","type":"multiple_choice"},{"correct_index":2,"explanation":"Science claims need named observations linked to the claim. The other choices miss a key step or use a common mistake.","options":["A label copied from the title with no evidence","Thinking “everyone online is a friend” is unsafe","A named observation plus how it supports the claim","A longer story with no observation"],"question":"Which record best supports a science claim about online safety?","type":"multiple_choice"},{"correct_index":1,"explanation":"The strongest choice applies the taught idea about online safety with evidence. The other choices miss a key step or use a common mistake.","options":["Ignore measurements and decide by which looks nicer","Safe; unsafe; safe","Thinking “everyone online is a friend” is unsafe","Change several conditions at once so something happens faster"],"question":"Using this science idea — Staying safe online means protecting personal information, asking trusted adults before sharing and — which choice is strongest?","type":"multiple_choice"},{"correct_index":1,"explanation":"Fair tests change one variable, control the rest, and use recorded evidence. The other choices miss a key step or use a common mistake.","options":["Ignore measurements and decide by which looks nicer","Change one variable and keep the other conditions the same","Change several conditions at once so something happens faster","Stop early when you like the first result"],"question":"Which investigation design best tests an idea about online safety?","type":"multiple_choice"},{"correct_index":1,"explanation":"Scientific predictions stay open to new observations rather than protecting a first guess. The other choices miss a key step or use a common mistake.","options":["Results that disagree with the first guess should be discarded","If the observed feature changes, the claim about online safety should change with it","Any exciting story about the object must be true","Thinking “everyone online is a friend” is unsafe"],"question":"Which prediction about online safety can be checked with evidence?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept a new example with named observations and a claim–evidence link about online safety. Reject title-only labels with no observation.","question":"Investigate or describe a fresh example (not the worked objects) that uses online safety. Record evidence and explain how it supports your claim.","sample_answer":"Sample: new object/context, two named observations, claim about online safety linked to that evidence.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception plus corrected claim and evidence reason for online safety. Reject wording changes that leave the same error.","question":"Name one science misconception about online safety, correct it with evidence, and say why the correction works.","sample_answer":"Sample misconception: Thinking “everyone online is a friend” is unsafe.. Correction: Safe; unsafe; safe. with evidence.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-sci-y3-w30-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise online safety.","Read the mission before you start observing or testing.","Keep the property or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations.","Say what each observation shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Digital Technologies","success_criteria":["I can use online safety with a specific example from this lesson.","I can identify personal and explain why it matters.","I can practise permission independently on a new prompt.","I can notice trust needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"Staying safe online means protecting personal information, asking trusted adults before sharing and being kind in digital spaces.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Staying safe online means protecting personal information, asking trusted adults before sharing and being kind in"],"question":"Which choice best applies this lesson idea about online safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nDo not share full name, address, school or passwords publicly. Ask before posting photos of others. Stop and tell an adult if something feels wrong.\n\nTRY FIRST\nSort safe/unsafe: using a class code; telling a stranger your address in chat; asking a parent before a new app.\n\nFEEDBACK\nSafe; unsafe; safe.","explain":"Staying safe online means protecting personal information, asking trusted adults before sharing and being kind in digital spaces.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Thinking “everyone online is a friend” is unsafe. Correct the claim or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Online safety habits.","caption":"Strangers are not automatic friends.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Protect</text><text x=\"28\" y=\"78\">personal information</text><text x=\"358\" y=\"42\">Ask</text><text x=\"358\" y=\"78\">trusted adult</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation matters most.","who":"pip"},{"text":"Name the observations, properties or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Do not share full name, address, school or passwords publicly. Ask before posting photos of others. Stop and tell an adu Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation matters most.\nJuno: Name the observations, properties or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Do not share full name, address, school or passwords publicly. Ask before posting photos of others. Stop and tell an adu Then write your own evidence."}}]},{"check":{"correct_index":1,"explanation":"Make the science idea visible: name the observation, property or test step you used and say why it supports the claim.","options":["An answer copied without understanding","Make the science idea visible: name the observation, property or test step you used and say why it supports the claim","A guess with no evidence","A claim unrelated to the observation or test"],"question":"Which choice best applies this lesson idea about online safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nDo not share full name, address, school or passwords publicly. Ask before posting photos of others. Stop and tell an adult if something feels wrong. Look at each observation, variable or design choice that carries the idea.\n\nTRY FIRST\nList the key observations or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, property or test step you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show scientific thinking. Correct the claim or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"More safety habits.","caption":"Eight-rule charter.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Share care</text><text x=\"28\" y=\"78\">photos need permission</text><text x=\"358\" y=\"42\">Stop</text><text x=\"358\" y=\"78\">tell an adult if wrong</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally incorrect claim as a comparison.","options":["An answer copied without understanding","Use an intentionally incorrect claim as a comparison","A guess with no evidence","A claim unrelated to the observation or test"],"question":"Which choice best applies this lesson idea about online safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nThinking “everyone online is a friend” is unsafe. Here is a more productive model: Do not share full name, address, school or passwords publicly. Ask before posting photos of others. Stop and tell an adult if something feels wrong.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nSafe; unsafe; safe.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Thinking “everyone online is a friend” is unsafe. Correct the claim or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the same science idea on a new object, material or context, not a copy of the worked example.","options":["A guess with no evidence","A claim unrelated to the observation or test","Use the same science idea on a new object, material or context, not a copy of the worked example","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about online safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nStaying safe online means protecting personal information, asking trusted adults before sharing and being kind in digital spaces. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInvestigate or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different objects or data.","explain":"Use the same science idea on a new object, material or context, not a copy of the worked example. Review accuracy of observations.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 3, Week 30, Lesson 1: Staying safe online","unit_number":6,"unit_title":"Digital technologies: data and coding","week":30,"week_in_unit":5,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nDo not share full name, address, school or passwords publicly. Ask before posting photos of others. Stop and tell an adult if something feels wrong.\n\nWrite what makes this example accurate, naming the observations, properties or test steps used.","worked_visuals":[{"alt":"Online safety habits.","caption":"Strangers are not automatic friends.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Protect</text><text x=\"28\" y=\"78\">personal information</text><text x=\"358\" y=\"42\">Ask</text><text x=\"358\" y=\"78\">trusted adult</text></g></svg>"},{"alt":"More safety habits.","caption":"Eight-rule charter.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Share care</text><text x=\"28\" y=\"78\">photos need permission</text><text x=\"358\" y=\"42\">Stop</text><text x=\"358\" y=\"78\">tell an adult if wrong</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-sci-y3-w30-l1' AND family_id IS NULL;
